const item = $input.first().json;
const reqKey = item.request_id || (item.customer_email + '|' + (item.message || '').slice(0, 60));
let h = 5381;
for (let i = 0; i < reqKey.length; i++) {
  h = ((h << 5) + h) + reqKey.charCodeAt(i);
  h |= 0;
}
const key = 'req_' + (h >>> 0).toString(16);
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k] > 24 * 3600 * 1000) delete store.seen[k];
}
const duplicate = Boolean(store.seen[key]);
if (!duplicate) store.seen[key] = now;
return [{ json: { ...item, idempotencyKey: key, duplicate } }];

